        item = [[CRData alloc] init];
        item.id = @"5111-0211";
        item.rating = @"3 рубля";
        item.title = @"К 350-летию добровольного вхождения Бурятии в состав Российского государства";
        item.serial = @"К 350-летию добровольного вхождения Бурятии в состав РФ";
        item.imageName1 = @"5111-0224-1";
