        item = [[CRData alloc] init];
        item.id = @"5111-0034";
        item.rating = @"3 рубля";
        item.title = @"Александр Невский. Новгородский кремль";
        item.serial = @"1000-летие России";
        item.imageName1 = @"5111-0034-1";
